using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CDApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_CeilingDensity/";static string O=>R+"/Docs/Review/2026-11-10_B2_CeilingDensity/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
 static Vector3 V(JToken p)=>new Vector3((float)p[0],(float)p[1],(float)p[2]);
 static Material Pipe(string n,Color c,float metal,float smooth){string path=E+"Materials/CD_"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Steel.mat"));m.name="CD_"+n;AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",c);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);m.SetFloat("_BumpScale",.20f);m.mainTextureScale=new Vector2(.6f,.6f);EditorUtility.SetDirty(m);return m;}
 public static object Import(){Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));mats["B2M_Plate"]=mats["B4O_Plate"];mats["B4O_Steel"]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Steel.mat");mats["B4O_Dark"]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BR_Dark.mat");mats["BM_Pipe"]=Pipe("Pipe",new Color(.82f,.86f,.88f),.85f,.43f);mats["BM_PipeRed"]=Pipe("PipeRed",new Color(.43f,.10f,.065f),.40f,.30f);int count=0;
 foreach(var path in Directory.GetFiles(E,"CD_*.fbx").Select(x=>x.Replace('\\','/'))){var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();count++;}AssetDatabase.SaveAssets();return new{models=count};}
 static GameObject Put(string name,Transform parent){var src=AssetDatabase.LoadAssetAtPath<GameObject>(E+name+".fbx");if(!src)throw new Exception("Missing "+name);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=name;g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;foreach(var f in g.GetComponentsInChildren<MeshFilter>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;var high=g.GetComponentsInChildren<Renderer>();var low=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(E+name+"_Far.fbx"),g.transform);low.name="Distance_LOD1";low.transform.localPosition=Vector3.zero;low.transform.localRotation=Quaternion.identity;var lod=g.AddComponent<LODGroup>();lod.fadeMode=LODFadeMode.CrossFade;lod.SetLODs(new[]{new LOD(.16f,high),new LOD(0,low.GetComponentsInChildren<Renderer>())});lod.RecalculateBounds();return g;}
 public static void Save(Scene s){foreach(var t in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object Reposition(){var s=Check();var plan=JObject.Parse(File.ReadAllText(H+"plan.json"));foreach(var p in plan["placements"]){var g=GameObject.Find((string)p["name"]);if(!g)throw new Exception("Missing "+p["name"]);g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);}Save(s);return "Updated positions and facing; scales preserved";}
 public static object Run(){var s=Check();if(GameObject.Find("CD_C02_CeilingServices"))throw new Exception("Already applied; scoped repair only");var p=JObject.Parse(File.ReadAllText(H+"plan.json"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();int scaled=0,added=0,moved=0;
 foreach(var c in JArray.Parse(File.ReadAllText(H+"changes.json"))){var row=c["after"];var name=(string)row["name"];GameObject g;if(c["before"].Type==JTokenType.Null){var src=all.Single(t=>t.name==(string)row["source"]);var room=GameObject.Find("B2_"+(string)row["room"]+"_Operations").transform;g=UnityEngine.Object.Instantiate(src.gameObject,room);g.name=name;g.SetActive(true);added++;}else{g=GameObject.Find(name);if(!g)throw new Exception("Missing "+name);moved++;}
 g.transform.localPosition=V(row["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)row["yaw"],0);if(row["relative_scale"]!=null){g.transform.localScale*=(float)row["relative_scale"];scaled++;}foreach(var lod in g.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();}
 foreach(var r in p["rooms"]){string id=(string)r["id"];var root=GameObject.Find("B2_"+id+"_Operations").transform;var old=root.Find("BO_"+id+"_OperationsServices");if(!old)throw new Exception("Original services missing "+id);old.gameObject.SetActive(false);Put("CD_"+id+"_OperationsServices",root);Put("CD_"+id+"_CeilingServices",root);}
 Put("CD_S01_MaintenanceGantry",GameObject.Find("B2_S01_Operations").transform);Put("CD_E03_WetProcessGantry",GameObject.Find("B2_E03_Operations").transform);foreach(var camera in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))camera.useOcclusionCulling=false;Save(s);Directory.CreateDirectory(O);var result=new{scaled,added,moved,ceilingRooms=12,newFrames=2,saved=!s.isDirty};File.WriteAllText(O+"applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
